1	// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
2	// against a member. Everything it decides was decided elsewhere: the flows judge and
3	// write, `terminalFor` says what happens to the PR, `deliveryFor` says whether the PR
4	// this run opens is the member's to land. What lives here is the I/O none of them may
5	// carry — the clone, the branch, the commit, the push, the PR, and the hand-off.
6	//
7	// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
8	// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
9	// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
10	// and let the shared landing helper own every nuance of arming versus merging. A
11	// second, cleverer shape here would be a second set of the same bugs.
12	//
13	// IT NO LONGER ASKS WHICH MECHANISM SERVES THE REPO. There is one, and its only
14	// rival was deleted in #768 Phase 5, so the question had exactly one answer for
15	// every member that could ask it; the `maintenance` block that held it is gone
16	// (#1252) and `engine/served-by.mjs` is deprecated with it.
17	import { execFileSync } from 'node:child_process';
18	import { readFileSync, existsSync, mkdtempSync, writeFileSync } from 'node:fs';
19	import { join } from 'node:path';
20	import { tmpdir } from 'node:os';
21	import { pathToFileURL } from 'node:url';
22	import { removeTree } from '../../../../engine/remove-tree.mjs';
23	import {
24	  deliveryFor, pullCreateError, landDelivery, openDeliveredPull, disposeOpenPull, withTaskTrailer,
25	} from '../../../claudinite-tasks/shared-code/delivery.mjs';
26	import { settingsPath, SETTINGS_FILE } from '../../../../engine/settings-file.mjs';
27	
28	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
29	const UPDATE_PREFIX = 'claudinite/update';
30	// What this worker stamps on everything it commits and merges (task-trailer.mjs).
31	const UPDATE_TASK_ID = 'claudinite-lifecycle/update';
32	const API = 'https://api.github.com';
33	
34	const git = (args, opts = {}) =>
35	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
36	
37	async function gh(token, path, { method = 'GET', body } = {}) {
38	  const res = await fetch(`${API}${path}`, {
39	    method,
40	    headers: {
41	      authorization: `Bearer ${token}`,
42	      accept: 'application/vnd.github+json',
43	      'x-github-api-version': '2022-11-28',
44	      ...(body ? { 'content-type': 'application/json' } : {}),
45	    },
46	    body: body ? JSON.stringify(body) : undefined,
47	  });
48	  let json = null;
49	  try { json = await res.json(); } catch { /* empty body */ }
50	  return { status: res.status, json };
51	}
52	
53	// --- pure helpers (exported, unit-tested git-free) --------------------------
54	
55	// One branch per run, dated and seeded like baselining's: two runs on one day must
56	// not collide, and a name that carries its date is one a human can read a week later.
57	// Minted only under an executor that hands no target in (DESIGN §6.4b) — see the
58	// tolerance in `main`, and #1698 for its removal.
59	export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;
60	
61	// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
62	// and exits 0 is worse than no gate at all — it reports a qualification that never
63	// happened — and that is not hypothetical: this exact gate went vacuous the day the
64	// canary flipped to `updates`, because the workflow drove the canary's baselining
65	// worker, which correctly stood down and exited 0 in zero seconds for weeks.
66	//
67	// So the rehearsal announces that it really ran, and the workflow fails when this
68	// line is absent. Any future path that skips the converge is caught by construction
69	// rather than by someone noticing a suspiciously fast green.
70	export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';
71	
72	// The PR title and body for a terminal. The body is what a human reads when the run
73	// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
74	// says "an update ran" makes every reader re-derive the thing the run already knew.
75	//
76	// THE TITLE IS A SUMMARY, THE BODY IS THE DETAIL. A title that names every moved pack
77	// grows with the number a member declares, and a PR list is where that is least
78	// readable — so the packs collapse to a count and only the engine keeps its versions.
79	export function updatePullText(terminal, { engine, packs }) {
80	  const engineMoved = engine?.from !== engine?.to;
81	  const movedPacks = (packs?.plan ?? []).filter((p) => p.from !== p.to);
82	  const moved = [
83	    ...(engineMoved ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
84	    ...movedPacks.map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
85	  ];
86	  const summary = [
87	    ...(engineMoved ? [`engine ${engine?.from == null ? 'unstamped' : `v${engine.from}`} → v${engine?.to}`] : []),
88	    ...(movedPacks.length ? [`${movedPacks.length} pack${movedPacks.length === 1 ? '' : 's'} upgraded`] : []),
89	  ];
90	  const title = summary.length ? `Claudinite update: ${summary.join(' and ')}` : 'Claudinite update';
91	  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
92	  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
93	  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
94	  if (terminal.action === 'needs-human') {
95	    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
96	  } else if (terminal.action === 'apply-stage') {
97	    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content before anything merges.');
98	  }
99	  return { title, body: `${lines.join('\n')}\n` };
100	}
101	
102	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
103	
104	export async function main() {
105	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
106	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
107	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
108	  const token = process.env.GITHUB_TOKEN;
109	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
110	  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
111	  // report, and restore the working tree — no branch, no commit, no PR, and above
112	  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
113	  // which is exactly what the next converge's anti-rewind guard refuses: a rehearsal
114	  // that wedges its own canary.
115	  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
116	  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
117	  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }
118	
119	  // Either settings-file name, in the rename's read order: this worker is VENDORED,
120	  // so the copy running on a member may predate the record that renamed its own
121	  // file — and one that only knew the new name would report "nothing to update" on
122	  // every repo still carrying the old one.
123	  const settingsFile = settingsPath(root);
124	  if (!existsSync(settingsFile)) { console.log(`update: no ${SETTINGS_FILE} — nothing to update`); return; }
125	  const declaration = JSON.parse(readFileSync(settingsFile, 'utf8'));
126	
127	  // One override, one direction: a repo that asked for review gets its PR opened and
128	  // left; every other repo — the normal shape, the key absent — has it landed.
129	  const delivery = deliveryFor(declaration);
130	
131	  // THE TARGET (tasks-dispatch DESIGN §6.4b). Which branch this run pushes to, and
132	  // what becomes of the previous cycle's pull request, is the executor's decision:
133	  // the task declares `supersede_existing_pr`, the executor resolved it before this
134	  // subprocess started — landing a green incumbent, or closing the rest once this
135	  // run's own pull request exists — and handed the branch in. Nothing here reads
136	  // the open pull requests or picks a name.
137	  const targetBranch = process.env.CLAUDINITE_TARGET_BRANCH || null;
138	  if (!targetBranch) {
139	    // AN EXECUTOR THAT PREDATES THE HAND-OFF sets no target, and then the disposal
140	    // this worker used to do on its own still has to happen, or incumbents pile up
141	    // (#787): a cycle that could not land its PR leaves it open for the next run,
142	    // and that disposal must precede the converge, because a cycle with nothing to
143	    // do returns early. Held for the convergence window #1698 closes.
144	    // @legacy-tolerance advisory:none retire:#1698
145	    const open = rehearsalRef ? { json: [] } : await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
146	    const incumbent = openDeliveredPull(open.json, UPDATE_PREFIX);
147	    if (incumbent) {
148	      const disposal = await disposeOpenPull({
149	        task: UPDATE_TASK_ID,
150	        token, repo, pr: incumbent, delivery, log: (s) => console.log(`update: ${s}`),
151	      }).catch((e) => { console.log(`update: disposing of PR #${incumbent.number} failed: ${e.message}`); return 'kept'; });
152	      if (disposal === 'kept') {
153	        console.log(`update: PR #${incumbent.number} still stands — this cycle cannot deliver on top of it`);
154	        return;
155	      }
156	      if (disposal === 'merged') {
157	        console.log(`update: landed PR #${incumbent.number}; main has moved past this checkout — next cycle converges from it`);
158	        return;
159	      }
160	    }
161	  }
162	
163	  // The flows run from a FRESH CANON CLONE, never from this repo's mount: the mount is
164	  // the thing being replaced, and a flow executing its own stale copy is how a broken
165	  // update makes itself permanent.
166	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
167	  try {
168	    // A rehearsal names the ref it is qualifying; an ordinary cycle takes the
169	    // default branch, which is the only thing a member should ever converge onto.
170	    git(rehearsalRef
171	      ? ['clone', '--depth', '1', '--branch', rehearsalRef, CANON_URL, tmp]
172	      : ['clone', '--depth', '1', CANON_URL, tmp]);
173	    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
174	    const { engineUpdate } = await load('packs/claudinite-lifecycle/updates/engine-update.mjs');
175	    const { packUpdate } = await load('packs/claudinite-lifecycle/updates/pack-update.mjs');
176	    const { terminalFor } = await load('packs/claudinite-lifecycle/updates/terminals.mjs');
177	
178	    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
179	    // pack flow enforces that against what this repo HAS. Running packs first would
180	    // check every pack against yesterday's engine and block updates that the very
181	    // next step would have made legal.
182	    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
183	    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
184	    let packs = null;
185	    if (engine.status !== 'needs-human') {
186	      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
187	      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
188	    }
189	
190	    // The engine's terminal wins when it stopped the run: nothing downstream of a
191	    // refused engine update is trustworthy, including a pack flow that never ran.
192	    const outcome = engine.status === 'needs-human' ? engine : packs;
193	    const terminal = terminalFor(outcome);
194	
195	    // A REHEARSAL STOPS HERE. It has the only answer it was asked for — does this
196	    // canon ref converge this member and leave it green — so it says so and puts the
197	    // tree back exactly as it found it. Restoring is not tidiness: an uncommitted
198	    // converge left behind would be picked up by the canary's own next cycle as if a
199	    // human had written it.
200	    if (rehearsalRef) {
201	      git(['-C', root, 'checkout', '--', '.']);
202	      git(['-C', root, 'clean', '-fd']);
203	      if (terminal.action === 'needs-human') {
204	        console.error(`update: rehearsing ${rehearsalRef} FAILED — ${terminal.why}`);
205	        process.exit(1);
206	      }
207	      console.log(`${REHEARSAL_MARKER} ${repo} against ${rehearsalRef} — ${terminal.action}: ${terminal.why}`);
208	      return;
209	    }
210	
211	    // AN APPLY STAGE IS NOT "NOTHING CHANGED" (#1545). A run that withheld a workflow
212	    // file leaves the pack unstamped, precisely so the record stays in range — so on a
213	    // cycle that re-stages content the branch already carries, the tree can be clean
214	    // while a delivery is still owed. Returning here would skip the PR, and the
215	    // apply-stage request is written below it, so nobody would ever be asked to deliver:
216	    // the silent loss this whole fix exists to end, one step further along. The empty
217	    // commit is the point — the apply stage's own move is what fills the PR.
218	    const changed = git(['-C', root, 'status', '--porcelain']).trim();
219	    if (!changed && terminal.action !== 'needs-human' && terminal.action !== 'apply-stage') {
220	      console.log('update: nothing changed — no branch, no PR');
221	      return;
222	    }
223	
224	    const day = new Date().toISOString().slice(0, 10);
225	    const seed = Math.random().toString(36).slice(2, 8);
226	    // The executor's branch where it handed one in; the runner's own only under an
227	    // executor that set none (the tolerance above).
228	    const branch = targetBranch ?? updateBranchName(day, seed);
229	    git(['-C', root, 'checkout', '-B', branch]);
230	    git(['-C', root, 'add', '-A']);
231	    const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
232	    const { title, body } = updatePullText(terminal, { engine, packs });
233	    git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
234	      // The trailer is what classifies this converge as machinery to every
235	      // movement-gated task: the mount refreshing is not the project moving.
236	      'commit', ...(staged.length ? [] : ['--allow-empty']), '-m', withTaskTrailer(title, UPDATE_TASK_ID)]);
237	    git(['-C', root, 'push', '--force', `https://x-access-token:${token}@github.com/${repo}.git`, `HEAD:refs/heads/${branch}`]);
238	
239	    const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
240	    const failure = pullCreateError(created.status, created.json);
241	    if (failure) throw new Error(`could not open the update PR for ${branch}: ${failure}`);
242	    const pr = created.json;
243	    console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);
244	
245	    // The terminal, acted on. Only one action merges, and it is the one the flow
246	    // already judged green — everything else leaves the PR standing, labelled or
247	    // handed to the agent stage.
248	    if (terminal.action === 'merge') {
249	      await landDelivery({ token, repo, base, pr, delivery, task: UPDATE_TASK_ID });
250	    } else if (terminal.action === 'needs-human') {
251	      await gh(token, `/repos/${repo}/issues/${pr.number}/labels`, { method: 'POST', body: { labels: [terminal.label] } });
252	      console.error(`update: left PR #${pr.number} open and labelled ${terminal.label} — ${terminal.why}`);
253	      // NON-ZERO, so the work item lands in `needs-human` rather than closing
254	      // `task:done`. This terminal means the converge DID NOT DELIVER — the PR
255	      // is parked awaiting a person — and a run that delivered nothing must not
256	      // report success. Exiting 0 here is what hid #939 for five days: every
257	      // member's nightly update closed `task:done` while its PR sat parked, so
258	      // the whole fleet was frozen and every signal said healthy. This is the
259	      // "reserve non-zero for genuine breakage" rule's genuine breakage: the
260	      // member is not converging and nothing else will say so.
261	      process.exitCode = 1;
262	    } else if (terminal.action === 'apply-stage' && requestFile) {
263	      writeFileSync(requestFile, `${JSON.stringify({
264	        marker: 'agent-requested',
265	        delivered: { branch, pr: pr.number, merged: false },
266	        reason: { code: 'apply-stage', detail: terminal.why },
